function(container, apiUrl, tables) {
  // 業務ロジックモジュールをインポート
  const { 
    collectSalesData, 
    classifySalesDataByProduct, 
    classifySalesDataByStore, 
    filterValidProductData,
    collectWeatherData,
    collectEventData,
    collectSeasonalData,
    analyzeCorrelationSalesWeather,
    analyzeCorrelationSalesEvent,
    analyzeCorrelationSalesSeason,
    compareWithHistoricalData,
    findAlternativeComparisonData,
    validateComparisonPeriod
  } = window.businessLogic || {};

  let currentApplyProcess = null;
  let selectedStores = new Set();

  // 現在日時を設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  const startDatetimeInput = container.querySelector('#start-datetime');
  if (startDatetimeInput) {
    startDatetimeInput.value = now.toISOString().slice(0, 16);
  }

  // DOM要素を取得
  const modelSelect = container.querySelector('#model-select');
  const storeList = container.querySelector('#store-list');
  const modelDetailsArea = container.querySelector('#model-details');
  const modelInfo = container.querySelector('#model-info');
  const validationResults = container.querySelector('#validation-results');
  const applyBtn = container.querySelector('#apply-btn');
  const cancelBtn = container.querySelector('#cancel-btn');
  const progressArea = container.querySelector('#progress-area');
  const progressBar = container.querySelector('#progress-bar');
  const progressText = container.querySelector('#progress-text');
  const logArea = container.querySelector('#log-area');
  const logContent = container.querySelector('#log-content');

  // モデル一覧を読み込み
  async function loadModels() {
    try {
      const models = await window.aivicApi.list(8); // 需要予測結果テーブル

      if (models && modelSelect) {
        // 検証済みモデルのみを表示（ステータスが「完了」のもの）
        const validatedModels = models.filter(m => m.予測ステータス === '完了');

        modelSelect.innerHTML = '<option value="">-- モデルを選択してください --</option>' +
          validatedModels.map(m => 
            `<option value="${m.予測結果ID}">${m.予測モデルバージョン} (精度: ${m.予測精度 || 'N/A'}%)</option>`
          ).join('');
      }
    } catch (error) {
      window.aivicNotify.error('モデル一覧の読み込みに失敗しました: ' + error.message);
    }
  }

  // 店舗一覧を読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ

      if (stores && storeList) {
        const activeStores = stores.filter(s => s.有効フラグ);
        storeList.innerHTML = activeStores.map(store => `
          <label style="display: flex; align-items: center; gap: 8px; margin-bottom: 8px; cursor: pointer;">
            <input type="checkbox" class="store-checkbox" value="${store.店舗ID}" style="margin: 0;">
            <span style="color: var(--text); font-size: 14px;">${store.店舗名} (${store.店舗コード})</span>
          </label>
        `).join('');

        // 店舗チェックボックスのイベントリスナーを追加
        const checkboxes = storeList.querySelectorAll('.store-checkbox');
        checkboxes.forEach(checkbox => {
          checkbox.addEventListener('change', function() {
            if (this.checked) {
              selectedStores.add(this.value);
            } else {
              selectedStores.delete(this.value);
            }
            updateApplyButtonState();
          });
        });
      }
    } catch (error) {
      window.aivicNotify.error('店舗一覧の読み込みに失敗しました: ' + error.message);
    }
  }

  // モデル詳細を表示
  async function showModelDetails(modelId) {
    try {
      const model = await window.aivicApi.get(8, modelId);

      if (model && modelInfo) {
        modelInfo.innerHTML = `
          <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">
            <div>
              <h4 style="margin: 0 0 8px 0; color: var(--text);">基本情報</h4>
              <p style="margin: 4px 0; color: var(--text-secondary); font-size: 14px;">モデルバージョン: ${model.予測モデルバージョン}</p>
              <p style="margin: 4px 0; color: var(--text-secondary); font-size: 14px;">作成日時: ${new Date(model.作成日時).toLocaleString()}</p>
              <p style="margin: 4px 0; color: var(--text-secondary); font-size: 14px;">予測精度: ${model.予測精度 || 'N/A'}%</p>
            </div>
            <div>
              <h4 style="margin: 0 0 8px 0; color: var(--text);">適用範囲</h4>
              <p style="margin: 4px 0; color: var(--text-secondary); font-size: 14px;">対象期間: ${model.予測開始日} ～ ${model.予測終了日}</p>
              <p style="margin: 4px 0; color: var(--text-secondary); font-size: 14px;">対象商品数: ${model.対象商品数 || 'N/A'}件</p>
            </div>
          </div>
        `;
      }

      // 検証結果を表示
      await showValidationResults(modelId);

      if (modelDetailsArea) {
        modelDetailsArea.style.display = 'block';
      }

      updateApplyButtonState();
    } catch (error) {
      window.aivicNotify.error('モデル詳細の読み込みに失敗しました: ' + error.message);
    }
  }

  // 検証結果を表示
  async function showValidationResults(modelId) {
    try {
      // 業務ロジックを使用して検証データを収集・分析
      const salesData = await collectSalesData();
      const weatherData = await collectWeatherData();
      const eventData = await collectEventData();
      const seasonalData = await collectSeasonalData();

      // 相関分析を実行
      const weatherCorrelation = analyzeCorrelationSalesWeather(salesData, weatherData);
      const eventCorrelation = analyzeCorrelationSalesEvent(salesData, eventData);
      const seasonCorrelation = analyzeCorrelationSalesSeason(salesData, seasonalData);

      // 履歴データとの比較
      const historicalComparison = compareWithHistoricalData(salesData);

      if (validationResults) {
        validationResults.innerHTML = `
          <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px;">
            <div style="padding: 12px; background: var(--surface); border-radius: 8px; border: 1px solid var(--border);">
              <h5 style="margin: 0 0 8px 0; color: var(--text);">天候相関</h5>
              <p style="margin: 0; color: var(--text-secondary); font-size: 14px;">相関係数: ${weatherCorrelation.correlation?.toFixed(3) || 'N/A'}</p>
            </div>
            <div style="padding: 12px; background: var(--surface); border-radius: 8px; border: 1px solid var(--border);">
              <h5 style="margin: 0 0 8px 0; color: var(--text);">イベント相関</h5>
              <p style="margin: 0; color: var(--text-secondary); font-size: 14px;">影響度: ${eventCorrelation.impact?.toFixed(3) || 'N/A'}</p>
            </div>
            <div style="padding: 12px; background: var(--surface); border-radius: 8px; border: 1px solid var(--border);">
              <h5 style="margin: 0 0 8px 0; color: var(--text);">季節性相関</h5>
              <p style="margin: 0; color: var(--text-secondary); font-size: 14px;">季節指数: ${seasonCorrelation.seasonality?.toFixed(3) || 'N/A'}</p>
            </div>
            <div style="padding: 12px; background: var(--surface); border-radius: 8px; border: 1px solid var(--border);">
              <h5 style="margin: 0 0 8px 0; color: var(--text);">履歴比較</h5>
              <p style="margin: 0; color: var(--text-secondary); font-size: 14px;">適合度: ${historicalComparison.fitness?.toFixed(3) || 'N/A'}</p>
            </div>
          </div>
        `;
      }
    } catch (error) {
      console.error('検証結果の表示でエラー:', error);
      if (validationResults) {
        validationResults.innerHTML = '<p style="color: var(--error); font-size: 14px;">検証結果の読み込みに失敗しました</p>';
      }
    }
  }

  // 適用ボタンの状態を更新
  function updateApplyButtonState() {
    const hasModel = modelSelect && modelSelect.value;
    const hasStores = selectedStores.size > 0;

    if (applyBtn) {
      applyBtn.disabled = !hasModel || !hasStores;
    }
  }

  // ログを追加
  function addLog(message, type = 'info') {
    if (logContent) {
      const timestamp = new Date().toLocaleTimeString();
      const logEntry = document.createElement('div');
      logEntry.style.cssText = `
        margin-bottom: 4px;
        font-size: 13px;
        color: ${type === 'error' ? 'var(--error)' : 'var(--text-secondary)'};
      `;
      logEntry.textContent = `[${timestamp}] ${message}`;
      logContent.appendChild(logEntry);
      logContent.scrollTop = logContent.scrollHeight;
    }
  }

  // 進捗を更新
  function updateProgress(percent, message) {
    if (progressBar) {
      progressBar.style.width = `${percent}%`;
    }
    if (progressText) {
      progressText.textContent = message;
    }
    addLog(message);
  }

  // モデル適用処理
  async function applyModel() {
    if (!modelSelect?.value || selectedStores.size === 0) {
      window.aivicNotify.error('モデルと店舗を選択してください');
      return;
    }

    try {
      // 進捗表示を開始
      if (progressArea) progressArea.style.display = 'block';
      if (logArea) logArea.style.display = 'block';
      if (applyBtn) applyBtn.disabled = true;
      if (cancelBtn) cancelBtn.disabled = false;

      updateProgress(0, '適用処理を開始しています...');

      const modelId = modelSelect.value;
      const storeIds = Array.from(selectedStores);
      const startDatetime = startDatetimeInput?.value;

      // 業務ロジックを使用してデータを収集
      updateProgress(10, '売上データを収集しています...');
      const salesData = await collectSalesData();

      updateProgress(20, '商品別データを分類しています...');
      const productData = classifySalesDataByProduct(salesData);

      updateProgress(30, '店舗別データを分類しています...');
      const storeData = classifySalesDataByStore(salesData);

      updateProgress(40, '有効な商品データをフィルタリングしています...');
      const validProductData = filterValidProductData(productData);

      updateProgress(50, '外部データを収集しています...');
      const weatherData = await collectWeatherData();
      const eventData = await collectEventData();
      const seasonalData = await collectSeasonalData();

      updateProgress(70, '相関分析を実行しています...');
      const weatherCorrelation = analyzeCorrelationSalesWeather(salesData, weatherData);
      const eventCorrelation = analyzeCorrelationSalesEvent(salesData, eventData);
      const seasonCorrelation = analyzeCorrelationSalesSeason(salesData, seasonalData);

      updateProgress(80, '履歴データと比較しています...');
      const historicalComparison = compareWithHistoricalData(salesData);

      // 適用結果を保存
      updateProgress(90, '適用結果を保存しています...');
      const applyResult = {
        適用ID: Date.now().toString(),
        予測結果ID: modelId,
        適用開始日時: startDatetime,
        対象店舗: storeIds.join(','),
        適用ステータス: '完了',
        作成日時: new Date().toISOString(),
        天候相関: weatherCorrelation.correlation,
        イベント相関: eventCorrelation.impact,
        季節相関: seasonCorrelation.seasonality,
        履歴適合度: historicalComparison.fitness
      };

      await window.aivicApi.save(9, applyResult); // モデル適用履歴テーブル

      updateProgress(100, '適用処理が完了しました');
      window.aivicNotify.success('モデルの本番適用が完了しました');

      // 完了後の処理
      setTimeout(() => {
        if (progressArea) progressArea.style.display = 'none';
        if (applyBtn) applyBtn.disabled = false;
        if (cancelBtn) cancelBtn.disabled = true;
      }, 2000);

    } catch (error) {
      addLog(`エラーが発生しました: ${error.message}`, 'error');
      window.aivicNotify.error('モデル適用に失敗しました: ' + error.message);

      if (applyBtn) applyBtn.disabled = false;
      if (cancelBtn) cancelBtn.disabled = true;
    }
  }

  // 適用処理をキャンセル
  function cancelApply() {
    if (currentApplyProcess) {
      currentApplyProcess.abort();
      currentApplyProcess = null;
    }

    if (progressArea) progressArea.style.display = 'none';
    if (applyBtn) applyBtn.disabled = false;
    if (cancelBtn) cancelBtn.disabled = true;

    addLog('適用処理がキャンセルされました', 'info');
    window.aivicNotify.info('適用処理をキャンセルしました');
  }

  // イベントリスナーを設定
  if (modelSelect) {
    modelSelect.addEventListener('change', function() {
      if (this.value) {
        showModelDetails(this.value);
      } else {
        if (modelDetailsArea) modelDetailsArea.style.display = 'none';
        updateApplyButtonState();
      }
    });
  }

  if (applyBtn) {
    applyBtn.addEventListener('click', applyModel);
  }

  if (cancelBtn) {
    cancelBtn.addEventListener('click', cancelApply);
  }

  // 初期化処理
  async function initialize() {
    try {
      await loadModels();
      await loadStores();
      updateApplyButtonState();

      // 初期状態では詳細エリアを非表示
      if (modelDetailsArea) modelDetailsArea.style.display = 'none';
      if (progressArea) progressArea.style.display = 'none';
      if (logArea) logArea.style.display = 'none';
      if (cancelBtn) cancelBtn.disabled = true;

    } catch (error) {
      window.aivicNotify.error('画面の初期化に失敗しました: ' + error.message);
    }
  }

  // 初期化を実行
  initialize();
}
